using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Checks whether the maximum number of owned public chats has been reached. Returns corresponding error if the limit was reached. The limit can be increased with Telegram Premium
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CheckCreatedPublicChatsLimitAsync(PublicChatType type = default)
    {

           using var activity =  StartCallActivity("CheckCreatedPublicChatsLimitAsync", typeof(CheckCreatedPublicChatsLimit).FullName ?? "CheckCreatedPublicChatsLimitAsync");

           try
           {
             return client.CheckCreatedPublicChatsLimitAsync(type);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
